import{_ as t,b as a,a as e,aS as o}from"./chunks/framework.M2Whok06.js";const b=JSON.parse('{"title":"autojs","description":"","frontmatter":{},"headers":[],"relativePath":"note/efficiency/autojs/index.md","filePath":"note/efficiency/autojs/index.md","lastUpdated":1742049167000}'),r={name:"note/efficiency/autojs/index.md"},p=o('<h1 id="autojs" tabindex="-1">autojs <a class="header-anchor" href="#autojs" aria-label="Permalink to &quot;autojs&quot;">​</a></h1><div class="tip custom-block github-alert"><p class="custom-block-title">替代方案</p><p>autox.js -&gt; doc.autoxjs.com <br> autojs6 -&gt; github.com <br> hamibot -&gt; github.com <br> robotjs -&gt; yooge.github.io <br></p></div><p>autoxjs : <a href="http://doc.autoxjs.com" target="_blank" rel="noreferrer">http://doc.autoxjs.com</a></p><h2 id="大厂时间" tabindex="-1">大厂时间 <a class="header-anchor" href="#大厂时间" aria-label="Permalink to &quot;大厂时间&quot;">​</a></h2><p>苏宁易购：<a href="http://quan.suning.com/getSysTime.do" target="_blank" rel="noreferrer">http://quan.suning.com/getSysTime.do</a></p><p>拼多多：<a href="https://api.pinduoduo.com/api/server/_stm" target="_blank" rel="noreferrer">https://api.pinduoduo.com/api/server/_stm</a></p><h2 id="淘宝时间" tabindex="-1">淘宝时间 <a class="header-anchor" href="#淘宝时间" aria-label="Permalink to &quot;淘宝时间&quot;">​</a></h2><h3 id="接口" tabindex="-1">接口 <a class="header-anchor" href="#接口" aria-label="Permalink to &quot;接口&quot;">​</a></h3><p>Date.now() 拿到的时间是基于设备时间计算出来的，如果两部手机设置的系统时间不一样，那在两部手机上分别执行 Date.now() 会拿到不一样的值。</p><p>有些用户会把手机的时间故意调快几分钟，所以我们在设计代码时，应该默认不信任 Date.now() 的值，尤其是后端需要和前端保持时间同步的情况。</p><p>一种解决方法是前后端均从同一个源头（Single source of truth）获取时间值，网上找到以下两个 API，淘宝的，可获取当前时间戳：</p><p><a href="http://api.m.taobao.com/rest/api3.do?api=mtop.common.getTimestamp" target="_blank" rel="noreferrer">http://api.m.taobao.com/rest/api3.do?api=mtop.common.getTimestamp</a></p><p><a href="http://acs.m.taobao.com/gw/mtop.common.getTimestamp/" target="_blank" rel="noreferrer">http://acs.m.taobao.com/gw/mtop.common.getTimestamp/</a> （可用）</p><h3 id="在线网站" tabindex="-1">在线网站 <a class="header-anchor" href="#在线网站" aria-label="Permalink to &quot;在线网站&quot;">​</a></h3><p><a href="http://time.syiban.com/t-taobao.php" target="_blank" rel="noreferrer">http://time.syiban.com/t-taobao.php</a></p><h3 id="淘宝ntp服务器" tabindex="-1">淘宝NTP服务器 <a class="header-anchor" href="#淘宝ntp服务器" aria-label="Permalink to &quot;淘宝NTP服务器&quot;">​</a></h3><p>淘宝NTP服务器：时间同步神器。</p><p>1、什么是淘宝NTP服务器</p><p>淘宝NTP服务器是淘宝官方提供的时间同步服务器，它可以帮助用户通过网络自动同步本地时间。NTP（Network Time Protocol，网络时间协议）是一种用于同步互联网上计算机时间的协议。淘宝NTP服务器是一种基于NTP协议的时间同步服务器，能够提供更加精准的时间服务。</p><p>淘宝NTP服务器具有以下特点：</p><p>1）可以通过互联网获取更加精准的时间信号。</p><p>2）淘宝NTP服务器使用NTP协议，有效保证了时间同步的准确性。</p><p>3）淘宝NTP服务器的可靠性非常高，不易出现故障。</p><p>2、为什么需要使用淘宝NTP服务器</p><p>电脑的时间同步非常重要，它不仅可以保证电脑上的各种软件正确运行，同时也对于文件的创建、编辑、修改和存储时标记的完整性和准确性有着至关重要的作用。而且，不同的计算机所配置的时间可能并不相同，如果存在时间误差，则可能会影响计算机之间的正常通讯和数据传输。</p><p>淘宝NTP服务器可以帮助用户通过互联网同步本地时间，保证时间的准确性，在计算机之间实现时间同步，避免时间误差，确保电脑间正常通讯和数据传输。</p><p>3、如何使用淘宝NTP服务器</p><p>使用淘宝NTP服务器非常简单，只需要按照以下步骤进行设置即可：</p><p>1）打开控制面板，找到“日期和时间”设置。</p><p>2）在“日期和时间”设置中，选择“Internet时间”选项卡。</p><p>3）在“Internet时间”选项卡中，选择“更改设置”。</p><p>4）在“更改设置”中，选择“更新现在时间”，勾选“同步服务器”选项，将“服务器”设置为：“time.taobao.com”。</p><p>5）单击“更新”按钮，电脑将自动同步淘宝NTP服务器提供的时间。</p>',33),i=[p];function n(s,c,m,h,l,d){return e(),a("div",null,i)}const _=t(r,[["render",n]]);export{b as __pageData,_ as default};
